   9   ChevronDown,
  10 } from 'lucide-react';
  11 import React, { useMemo, useState } from 'react';
  12 import { Checkbox } from "@/components/ui/checkbox";
  13 import { SectionAccordionItem } from './SectionAccordionItem';
  14 import { useBuilderStore } from "@/hooks";
  15 import { cn } from '@/infrastructure/utils/cn';
  16 import { v4 as uuidv4 } from 'uuid';
  17 import { motion, AnimatePresence } from 'framer-motion';
  18 
  19 interface SortableChapterItemProps {
  20   chapter: Chapter;
  21   index: number;
  22   isProjectBuildMode: boolean;
  23   selectedSectionsForBuild: Set<string>;
  24   toggleChapterSelection: (chapterId: string, select: boolean) => void;
  25   toggleSectionSelection: (sectionId: string) => void;
  26   activeSectionId: string | null;
  27   selectedSectionIds?: string[];
  28   onActivateSection: (sectionId: string, multiSelect?: boolean) => void;
  29   onActivate?: () => void;
  30   isActive?: boolean;
  31 }
  32 
  33 export function SortableChapterItem({
  34   chapter,
  35   index,
  36   isProjectBuildMode,
  37   selectedSectionsForBuild,
  38   toggleChapterSelection,
  39   toggleSectionSelection,
  40   activeSectionId,
  41   selectedSectionIds = [],
  42   onActivateSection,
  43   onActivate,
  44   isActive,
  45 }: SortableChapterItemProps) {
  46     const { 
  47         updateProject
  48     } = useBuilderStore(state => ({
  49         updateProject: state.updateProject,
  50     }));
  51     
  52   const [isCollapsed, setIsCollapsed] = useState(false);
  53   const { attributes, listeners, setNodeRef, transform, transition, isDragging } = useSortable({ id: chapter.id });
  54 
  55   const style: React.CSSProperties = {
  56     transform: CSS.Transform.toString(transform),
  57     transition,
  58     zIndex: isDragging ? 2 : 0,
  59     position: 'relative',
  60   };
  61 
  62   const sectionsInChapter = chapter.sections;
  63   const isAllSectionsSelected = useMemo(() => {
  64     if (sectionsInChapter.length === 0) return false;
  65     return sectionsInChapter.every(s => selectedSectionsForBuild.has(s.id));
  66   }, [sectionsInChapter, selectedSectionsForBuild]);
  67 
  68   const isSomeSectionsSelected = useMemo(() => {
  69     if (sectionsInChapter.length === 0) return false;
  70     const hasSelected = sectionsInChapter.some(s => selectedSectionsForBuild.has(s.id));
  71     return hasSelected && !isAllSectionsSelected;
  72   }, [sectionsInChapter, selectedSectionsForBuild, isAllSectionsSelected]);
  73 
  74   const handleAddSection = (chapterId: string) => {
  75     updateProject(p => p.addSectionToChapter(chapterId, uuidv4(), 'Untitled Section'));
  76   }
  77 
  78   return (
  79     <div ref={setNodeRef} style={style} {...attributes} className="group/chapter-container">
  80       <div className={cn(
  81         "relative bg-card/40 border rounded-2xl shadow-sm overflow-hidden transition-all duration-300 hover:translate-x-0.5",
  82         isActive 
  83             ? "border-primary/30 bg-primary/[0.02] shadow-[0_4px_20px_rgba(0,0,0,0.04)] ring-1 ring-primary/10" 
  84             : "border-border/60 hover:border-primary/20 hover:shadow-md"
  85       )}>
  86         <div 
  87           className={cn(
  88             "flex items-center px-4 py-2.5 cursor-pointer border-b transition-colors",
  89             isActive ? "bg-primary/[0.04] border-primary/10" : "bg-muted/10 hover:bg-muted/20 border-border/40"
  90           )}
  91           onClick={() => onActivate?.()}
  92         >
  93           {isProjectBuildMode && (
  94             <div className="flex items-center gap-2 mr-3" onClick={(e) => e.stopPropagation()}>
  95               <Checkbox
  96                 id={`select-chapter-${chapter.id}`}
  97                 checked={isAllSectionsSelected}
  98                 aria-checked={isSomeSectionsSelected ? 'mixed' : isAllSectionsSelected}
  99                 onCheckedChange={(checked: any) => toggleChapterSelection(chapter.id, !!checked)}
 100                 className="h-4 w-4 rounded-md"
 101               />
 102             </div>
 103           )}
 104           
 105           <div className="flex-1 py-0 min-w-0">
 106             <div className="flex items-center gap-3 flex-1 min-w-0 group">
 107               {listeners && (
 108                 <div 
 109                     {...listeners} 
 110                     className="p-1.5 rounded-lg cursor-grab touch-none -ml-2 flex items-center gap-2 text-muted-foreground/40 transition-all hover:bg-background/80 hover:text-primary active:cursor-grabbing" 
 111                     onClick={(e) => e.stopPropagation()}
 112                 >
 113                   <span className="text-[10px] w-4 text-center font-black uppercase tracking-[0.2em] tabular-nums">{index + 1}</span>
 114                   <GripVertical className="h-4 w-4 opacity-40 group-hover:opacity-100" />
 115                 </div>
 116               )}
 117               
 118               <div className="flex flex-col flex-1 min-w-0 text-left">
 119                 <span className={cn(
 120                     "text-[11px] font-black uppercase tracking-[0.2em] transition-colors duration-300",
 121                     isActive ? "text-primary" : "text-muted-foreground/80 group-hover:text-primary"
 122                 )}>
 123                     {chapter.title || 'UNTITLED CHAPTER'}
 124                 </span>
 125                 <span className="text-[9px] font-black text-primary/40 uppercase tracking-[0.25em] mt-0.5">
 126                     {sectionsInChapter.length} Sections Integrated
 127                 </span>
 128               </div>
 129               
 130               <Button
 131                 variant="ghost"
 132                 size="icon"
 133                 className={cn(
 134                     "h-8 w-8 rounded-xl transition-all duration-300",
 135                     isActive ? "bg-primary/10 text-primary" : "hover:bg-primary/5 hover:text-primary text-muted-foreground/60"
 136                 )}
 137                 onClick={(e) => {
 138                   e.stopPropagation();
 139                   setIsCollapsed(!isCollapsed);
 140                 }}
 141               >
 142                 <ChevronDown className={cn(
 143                   "h-4 w-4 transition-transform duration-500 cubic-bezier(0.4, 0, 0.2, 1)",
 144                   isCollapsed && "-rotate-90"
 145                 )} />
 146               </Button>
 147             </div>
 148           </div>
 149         </div>
 150         
 151         <AnimatePresence initial={false}>
 152           {!isCollapsed && (
 153             <motion.div 
 154               initial={{ height: 0, opacity: 0 }}
 155               animate={{ height: "auto", opacity: 1 }}
 156               exit={{ height: 0, opacity: 0 }}
 157               transition={{ duration: 0.5, ease: [0.22, 1, 0.36, 1] }}
 158               className="overflow-hidden"
 159             >
 160               <div className="p-4 bg-muted/5 relative">
 161                 {/* Visual depth vertical line */}
 162                 <div className="absolute left-6 top-0 bottom-10 w-px bg-gradient-to-b from-border/60 via-primary/10 to-transparent" />
 163                 
 164                 <div className="w-full space-y-2.5 pl-6 rtl:pl-0 rtl:pr-6">
 165                   {chapter.sections.map((section, sectionIndex) => (
 166                     <SectionAccordionItem
 167                       key={section.id}
 168                       section={section}
 169                       sectionIndex={sectionIndex}
 170                       chapterIndex={index}
 171                       isProjectBuildMode={isProjectBuildMode}
 172                       isSelected={selectedSectionsForBuild.has(section.id)}
 173                       toggleSectionSelection={toggleSectionSelection}
 174                       isActive={selectedSectionIds.includes(section.id)}
 175                       onActivate={onActivateSection}
 176                     />
 177                   ))}
 178 
 179                   <Button 
 180                     size="sm" 
 181                     variant="ghost" 
 182                     onClick={(e) => { e.stopPropagation(); handleAddSection(chapter.id); }} 
 183                     className="w-full h-9 text-[9px] font-black uppercase tracking-[0.2em] gap-2 hover:bg-primary/5 hover:text-primary border border-dashed border-border/60 hover:border-primary/30 transition-all duration-300 rounded-xl mt-4 text-muted-foreground/60"
 184                   >
 185                     <PlusCircle className="h-3.5 w-3.5" />
 186                     Integrate Neural Node
 187                   </Button>
 188                 </div>
 189               </div>
 190             </motion.div>
 191           )}
 192         </AnimatePresence>
 193       </div>
 194     </div>
 195   );
 196 };
